import { SelectAction } from "./select.actionTypes";
import { selectListReducer } from "../selectList/selectList.reducer";
import { ListAction } from "../selectList/selectList.actionTypes";
export const selectReducer = (state, action) => {
    const { type, payload } = action;
    switch (type) {
        case SelectAction.Expand: {
            const newState = selectListReducer(state, { type: ListAction.Focus, payload: { items: payload.items, multiselect: false } });
            return Object.assign(Object.assign(Object.assign({}, state), newState), { expanded: true });
        }
        case SelectAction.Collapse: {
            return Object.assign(Object.assign({}, state), { activeIndex: -1, expanded: false });
        }
        case SelectAction.CollapseAndSelect: {
            const newState = selectListReducer(state, { type: ListAction.Blur, payload: { multiselect: false } });
            return Object.assign(Object.assign(Object.assign({}, state), newState), { expanded: false });
        }
        case SelectAction.FocusFirstAndExpand: {
            const listState = selectListReducer(state, { type: ListAction.FocusFirst, payload: { items: payload.items } });
            return Object.assign(Object.assign(Object.assign({}, state), listState), { expanded: true });
        }
        case SelectAction.SearchAndExpand: {
            const listState = selectListReducer(state, { type: ListAction.SearchItem, payload: { items: payload.items, key: payload.key } });
            return Object.assign(Object.assign(Object.assign({}, state), listState), { expanded: true });
        }
        default: {
            const newSelectListState = selectListReducer(state, action);
            const expanded = newSelectListState.isItemsStateChanged ? false : state.expanded;
            return Object.assign(Object.assign(Object.assign({}, state), newSelectListState), { expanded });
        }
    }
};
